import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < k; i++) {
            v[sc.nextInt()] = 1;
        }
        int[] result = {1};
        int p = n / 2;
        while (p > 0) {
            if ((p & 1) == 1) {
                result = convolve(result, v, 998244353);
            }
            v = convolve(v, v, 998244353);
            p >>= 1;
        }
        long total = 0;
        for (int x : result) {
            total += (long) x * x;
        }
        System.out.println(total % 998244353);
    }

    static int[] convolve(int[] a, int[] b, int mod) {
        int size = 1;
        while (size < a.length + b.length - 1) size <<= 1;
        double[] A = new double[size];
        double[] B = new double[size];
        for (int i = 0; i < a.length; i++) A[i] = a[i];
        for (int i = 0; i < b.length; i++) B[i] = b[i];
        fft(A, false);
        fft(B, false);
        for (int i = 0; i < size; i++) A[i] *= B[i];
        fft(A, true);
        int[] res = new int[a.length + b.length - 1];
        for (int i = 0; i < res.length; i++) {
            res[i] = (int) Math.round(A[i]) % mod;
        }
        return res;
    }

    static void fft(double[] a, boolean invert) {
        int n = a.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j >= bit; bit >>= 1) {
                j -= bit;
            }
            j += bit;
            if (i < j) {
                double temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }
        }
        for (int len = 2; len <= n; len <<= 1) {
            double angle = 2 * Math.PI / len * (invert ? -1 : 1);
            double wlenCos = Math.cos(angle);
            double wlenSin = Math.sin(angle);
            for (int i = 0; i < n; i += len) {
                double wCos = 1;
                double wSin = 0;
                for (int j = 0; j < len / 2; j++) {
                    int u = i + j;
                    int v = i + j + len / 2;
                    double uVal = a[u];
                    double vVal = a[v] * wCos + a[v] * wSin;
                    a[u] = uVal + vVal;
                    a[v] = uVal - vVal;
                    double tempW = wCos;
                    wCos = wCos * Math.cos(angle) - wSin * Math.sin(angle);
                    wSin = wSin * Math.cos(angle) + tempW * Math.sin(angle);
                }
            }
        }
        if (invert) {
            for (int i = 0; i < n; i++) {
                a[i] /= n;
            }
        }
    }
}
